#include <zephyr/ztest.h>
#include <zephyr/kernel.h>

static K_THREAD_STACK_DEFINE(helper_stack, 512);
static struct k_thread helper_thread;
static volatile bool cleanup_executed;
static K_SEM_DEFINE(sem, 0, 1);

static void cleanup_handler(struct k_thread *thread)
{
	zassert_equal(thread, &helper_thread, "thread mismatch");
	cleanup_executed = true;
}

static void custom_cleanup_helper(k_tid_t thread, void *value)
{
	*(bool *)value = true;
}

static void helper_thread_entry(void *p1, void *p2, void *p3)
{
	/* do nothing */
}

static void helper_thread_entry_custom(void *p1, void *p2, void *p3)
{
	k_thread_custom_data_set(p1);
}

static void helper_thread_entry_sem(void *p1, void *p2, void *p3)
{
	k_sem_take(&sem, K_FOREVER);
}

ZTEST(cleanup_api, test_cleanup_register)
{
	struct k_thread_cleanup_info info;
	k_tid_t tid;

	cleanup_executed = false;

	tid = k_thread_create(&helper_thread, helper_stack, K_THREAD_STACK_SIZEOF(helper_stack),
			      helper_thread_entry, NULL, NULL, NULL, 0, 0, K_NO_WAIT);

	k_thread_cleanup_register(&info, tid, cleanup_handler);
	k_thread_join(tid, K_FOREVER);
	zassert_true(cleanup_executed, "cleanup handler was not executed");
}

ZTEST(cleanup_api, test_cleanup_cancel)
{
	struct k_thread_cleanup_info info;
	k_tid_t tid;

	cleanup_executed = false;

	tid = k_thread_create(&helper_thread, helper_stack, K_THREAD_STACK_SIZEOF(helper_stack),
			      helper_thread_entry_sem, NULL, NULL, NULL, 0, 0, K_NO_WAIT);

	k_thread_cleanup_register(&info, tid, cleanup_handler);
	zassert_false(cleanup_executed, "cleanup handler was executed prematurely");
	k_thread_cleanup_cancel(&info, tid);
	k_sem_give(&sem);
	k_thread_join(tid, K_FOREVER);
	zassert_false(cleanup_executed, "cleanup handler was executed after being cancelled");
}

ZTEST(cleanup_api, test_custom_cleanup_helper)
{
	k_tid_t tid;
	bool custom_cleanup_executed = false;

	tid = k_thread_create(&helper_thread, helper_stack, K_THREAD_STACK_SIZEOF(helper_stack),
			      helper_thread_entry_custom, &custom_cleanup_executed, NULL, NULL,
			      0, 0, K_NO_WAIT);

	k_thread_custom_data_set_cleanup(tid, custom_cleanup_helper);
	k_thread_join(tid, K_FOREVER);
	zassert_true(custom_cleanup_executed, "cleanup handler was not executed");
}

ZTEST_SUITE(cleanup_api, NULL, NULL, NULL, NULL, NULL);
